const I18nContext = createContext(null);

function plural(n, s) {
  return n === 1 ? '' : s;
}

function interpolate(template, vars = {}) {
  return String(template || '').replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
}

export function I18nProvider({ children }) {
  const [lang, setLangState] = useState(detectLanguage);

  const setLang = useCallback((next) => {
    if (next === 'auto') {
      try { localStorage.removeItem(LANG_KEY); } catch { /* ignore */ }
      setLangState(detectLanguage());
      return;
    }
    if (!SUPPORTED_LANGS.some((l) => l.code === next)) return;
    try { localStorage.setItem(LANG_KEY, next); } catch { /* ignore */ }
    setLangState(next);
  }, []);

  useEffect(() => {
    try {
      document.documentElement.lang = lang;
    } catch { /* ignore */ }
  }, [lang]);

  const value = useMemo(() => {
    const dict = STRINGS[lang] || STRINGS.en;
    const t = (key, vars) => interpolate(dict[key] ?? STRINGS.en[key] ?? key, vars);
    return { lang, setLang, t };
  }, [lang, setLang]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used within I18nProvider');
  return ctx;
}

export { STRINGS };